local dir=debug.getinfo(1,'S').source:sub(2):match('^(.*)[/\\]');package.path=dir..'/?.lua;'..package.path
local c=require('common');local o=c.options(arg);local forbidden={master_seed=true,canonical_entity_id=true,raw_ecs_id=true,other_team_state=true};local findings={};local function walk(value,p)if type(value)~='table'then return end;local array=#value>0;if array then for i,child in ipairs(value)do walk(child,p..'['..(i-1)..']')end else for key,child in pairs(value)do if forbidden[key]then table.insert(findings,p..'.'..key)end;walk(child,p..'.'..key)end end end;local input=assert(o.positional[1],'input required');walk(c.load_json(input),'$');table.sort(findings);c.write_result(o.output,{input=input,findings=findings,passed=#findings==0});if #findings>0 then os.exit(2)end
